ON CONFLICT (kostentraeger_ik, verknuepfungsart, partner_ik, abrechnungscode, art_datenlieferung, uebermittlungsmedium, bundesland) DO UPDATE SET
  leistungserbringergruppe=EXCLUDED.leistungserbringergruppe, quelle=EXCLUDED.quelle;
DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.kostentraeger_annahmestellen;
  IF n < 11409 THEN RAISE EXCEPTION 'seed kostentraeger_annahmestellen: % Zeilen, erwartet >= 11409', n; END IF;
END $$;
